package com.smartdairy.controller;
import com.smartdairy.entity.Expense; import com.smartdairy.service.ExpenseService; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.sql.Date;
public class ExpenseController extends HttpServlet{private final ExpenseService service=new ExpenseService(); protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{Expense e=new Expense();e.setExpenseDate(Date.valueOf(r.getParameter("expense_date")));e.setCategory(r.getParameter("category"));e.setAmount(Double.parseDouble(r.getParameter("amount")));e.setDescription(r.getParameter("description"));e.setPaymentMethod(r.getParameter("payment_method"));service.save(e);s.sendRedirect("expense.jsp?success=true");}catch(Exception ex){s.sendRedirect("expense.jsp?error=true");}}}
